/// <summary>
/// disable input to ItemRelation when ItemCode == TableGroupAll::All
/// PaffH 07.10.21
/// </summary>
/// <param name="sender">FormDataObject</param>
/// <param name="e">FormDataFieldEventArgs</param>
[FormDataFieldEventHandler(formDataFieldStr(NDXLimitGroupsWithFactors, KCS_LimitFactors, ItemCode), FormDataFieldEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'The parameter ist not required in this context')]
public static void ItemCode_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource  kCS_LimitFactors_ds = sender.datasource();
    KCS_LimitFactors kCS_LimitFactors = kCS_LimitFactors_ds.cursor();

    kCS_LimitFactors_ds.object(fieldNum(KCS_LimitFactors, ItemRelation)).enabled(kCS_LimitFactors.ItemCode != TableGroupAll::All);
    if (kCS_LimitFactors.ItemCode == TableGroupAll::All)
    {
        kCS_LimitFactors.ItemRelation = '';
    }

}

/// <summary>
/// disable input to ItemRelation when ItemCode == TableGroupAll::All
/// PaffH 07.10.21
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(NDXLimitGroupsWithFactors, KCS_LimitFactors), FormDataSourceEventType::Activated),
    SuppressBPWarning('BPParameterNotUsed', 'The parameter ist not required in this context')]
public static void KCS_LimitFactors_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    KCS_LimitFactors kCS_LimitFactors = sender.cursor() as KCS_LimitFactors;

    sender.object(fieldNum(KCS_LimitFactors, ItemRelation)).enabled(kCS_LimitFactors.ItemCode != TableGroupAll::All);
}
